    # Connected components of each nonzero color.
    by_color = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                by_color.setdefault(grid[r][c], set()).add((r, c))

    def components(cells):
        cells = set(cells)
        result = []
        while cells:
            start = cells.pop()
            comp = {start}
            stack = [start]
            while stack:
                r, c = stack.pop()
                for p in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if p in cells:
                        cells.remove(p)
                        comp.add(p)
                        stack.append(p)
            result.append(comp)
        return result

    # The largest component of color 1 is the silhouette template.
    shape = max(components(by_color[1]), key=len)
    r0, r1 = min(r for r,c in shape), max(r for r,c in shape)
    c0 = min(c for r,c in shape)
    pattern = [(r-r0, c-c0) for r,c in shape]
    sh = r1-r0+1

    # Remaining nonzero cells form the palette strip.
    palette = [(r,c) for r in range(h) for c in range(w)
               if grid[r][c] != 0 and (r,c) not in shape]
    pr0, pr1 = min(r for r,c in palette), max(r for r,c in palette)
    pc0, pc1 = min(c for r,c in palette), max(c for r,c in palette)

    if pc1-pc0 >= pr1-pr0:
        colors = [grid[pr0][c] for c in range(pc0, pc1+1) if grid[pr0][c]]
    else:
        colors = [grid[r][pc0] for r in range(pr0, pr1+1) if grid[r][pc0]]

    anchor = colors.index(1)
    out = [[0]*w for _ in range(h)]
